+  const res = await handle({ method: "POST", path: "/recipes/2/cook", body: { portions: 10 } });
+  assert.equal(res.status, 200);
+  const milk1022 = store.data.batches.find((b) => b.lot === "HD-1022");
+  const milk1026 = store.data.batches.find((b) => b.lot === "HD-1026");
+  assert.equal(milk1022.qty, 0);
+  assert.equal(milk1026.qty, 8);
